<?php

declare(strict_types=1);

/* @autogenerated */

namespace Tests\integration\Features\OAuth;

use DI\ContainerBuilder;
use Nimbly\Capsule\Factory\ServerRequestFactory;
use PHPUnit\Framework\TestCase;
use Psr\EventDispatcher\EventDispatcherInterface;
use Psr\SimpleCache\CacheInterface;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\SessionStoreGateway;
use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\TemporalKeysGateway;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Gateway\TokenSigner;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Gateway\TokenStoreGateway;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Gateway\TokenRevocationGateway;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\KeyConfig;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Infrastructure\Driven\JoseTokenSigner;
use Civi\Lughauth\Features\OAuth\Par\Domain\Gateway\ParRequestGateway;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\LoginGateway;
use Civi\Lughauth\Features\OAuth\Device\Domain\Gateway\DeviceAuthorizationGateway;
use Tests\integration\Features\OAuth\Stub\InMemoryClientStore;
use Tests\integration\Features\OAuth\Stub\InMemoryDeviceAuthorizationGateway;
use Tests\integration\Features\OAuth\Stub\InMemoryLoginGateway;
use Tests\integration\Features\OAuth\Stub\InMemoryParRequestStore;
use Tests\integration\Features\OAuth\Stub\InMemorySessionStore;
use Tests\integration\Features\OAuth\Stub\InMemoryTemporalKeys;
use Tests\integration\Features\OAuth\Stub\InMemoryTokenRevocation;
use Tests\integration\Features\OAuth\Stub\InMemoryTokenStore;

abstract class OidcIntegrationTestCase extends TestCase
{
    protected const string TENANT = 'tenant1';
    protected const string CLIENT_ID = 'test-client';
    protected const string CLIENT_SECRET = 'test-secret';
    protected const string USER_ID = 'user-123';
    protected const string USERNAME = 'testuser';
    protected const string PASSWORD = 'testpass';

    protected InMemoryClientStore $clientStore;
    protected InMemoryTokenStore $tokenStore;
    protected InMemoryTemporalKeys $temporalKeys;
    protected InMemorySessionStore $sessionStore;
    protected InMemoryParRequestStore $parStore;
    protected InMemoryTokenRevocation $tokenRevocation;
    protected InMemoryLoginGateway $loginGateway;
    protected \DI\Container $container;
    protected Context $context;

    protected function setUp(): void
    {
        parent::setUp();

        $_SERVER['HTTPS'] = 'off';
        $_SERVER['HTTP_HOST'] = 'localhost';
        $_SERVER['SCRIPT_NAME'] = '/index.php';

        $this->clientStore = InMemoryClientStore::withDefaults();
        $this->tokenStore = InMemoryTokenStore::withGeneratedKey(self::TENANT);
        $this->temporalKeys = new InMemoryTemporalKeys();
        $this->sessionStore = new InMemorySessionStore();
        $this->parStore = new InMemoryParRequestStore();
        $this->tokenRevocation = new InMemoryTokenRevocation();
        $this->loginGateway = InMemoryLoginGateway::withDefaults();

        $builder = new ContainerBuilder();
        $config = $this->createAppConfig();
        $this->context = new Context($builder, $config);

        $tokenStore = $this->tokenStore;
        $keyConfig = new KeyConfig();
        $cache = new class () implements CacheInterface {
            private array $items = [];

            public function get(string $key, mixed $default = null): mixed
            {
                return $this->items[$key] ?? $default;
            }

            public function set(string $key, mixed $value, null|int|\DateInterval $ttl = null): bool
            {
                $this->items[$key] = $value;
                return true;
            }

            public function delete(string $key): bool
            {
                unset($this->items[$key]);
                return true;
            }

            public function clear(): bool
            {
                $this->items = [];
                return true;
            }

            public function getMultiple(iterable $keys, mixed $default = null): iterable
            {
                $result = [];
                foreach ($keys as $key) {
                    $result[$key] = $this->get((string) $key, $default);
                }
                return $result;
            }

            public function setMultiple(iterable $values, null|int|\DateInterval $ttl = null): bool
            {
                foreach ($values as $key => $value) {
                    $this->set((string) $key, $value, $ttl);
                }
                return true;
            }

            public function deleteMultiple(iterable $keys): bool
            {
                foreach ($keys as $key) {
                    $this->delete((string) $key);
                }
                return true;
            }

            public function has(string $key): bool
            {
                return array_key_exists($key, $this->items);
            }
        };

        $signer = new JoseTokenSigner($keyConfig, $tokenStore, $cache);

        $builder->addDefinitions([
            ClientStoreGateway::class => $this->clientStore,
            SessionStoreGateway::class => $this->sessionStore,
            TemporalKeysGateway::class => $this->temporalKeys,
            TokenStoreGateway::class => $this->tokenStore,
            TokenSigner::class => $signer,
            TokenRevocationGateway::class => $this->tokenRevocation,
            ParRequestGateway::class => $this->parStore,
            LoginGateway::class => $this->loginGateway,
            DeviceAuthorizationGateway::class => new InMemoryDeviceAuthorizationGateway(),
            KeyConfig::class => $keyConfig,
            JoseTokenSigner::class => $signer,
            Context::class => $this->context,
            AppConfig::class => $config,
            EventDispatcherInterface::class => new class () implements EventDispatcherInterface {
                public function dispatch(object $event): object
                {
                    return $event;
                }
            },
        ]);

        $this->container = $builder->build();
    }

    protected function createAppConfig(): AppConfig
    {
        $config = $this->createStub(AppConfig::class);
        $config->method('get')->willReturnCallback(function (string $key, mixed $default = null): mixed {
            return match ($key) {
                'app.id.name' => 'lughauth-test',
                'app.id.namespace' => 'test',
                'app.id.version' => '1.0.0',
                'app.id.instance' => 'test-instance',
                'app.id.enviroment' => 'test',
                default => $default,
            };
        });
        return $config;
    }

    protected function makeRequest(string $method, string $uri, array $body = [], array $server = []): \Psr\Http\Message\ServerRequestInterface
    {
        $factory = new ServerRequestFactory();
        $request = $factory->createServerRequest($method, $uri, $server);
        if ($body !== []) {
            $request = $request->withParsedBody($body);
        }
        return $request;
    }

    protected function decodeJson(\Psr\Http\Message\ResponseInterface $response): array
    {
        return json_decode((string) $response->getBody(), true) ?? [];
    }

    protected function assertJsonField(\Psr\Http\Message\ResponseInterface $response, string $field): string
    {
        $data = $this->decodeJson($response);
        $this->assertArrayHasKey($field, $data, "Response body missing field '{$field}'");
        return (string) $data[$field];
    }
}
